import{_ as a,o as t,c as i,ae as o}from"./chunks/framework.B2ul6ABY.js";const m=JSON.parse('{"title":"Saivage v3 — Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),s={name:"troubleshooting.md"};function r(n,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="saivage-v3-—-troubleshooting" tabindex="-1">Saivage v3 — Troubleshooting <a class="header-anchor" href="#saivage-v3-—-troubleshooting" aria-label="Permalink to &quot;Saivage v3 — Troubleshooting&quot;">​</a></h1><p>Use this guide for current source-verified failure modes and operator-visible states.</p><p>For analyst-specific behavior such as chat-panel entry points, shell-command safety classes, the secret-path denylist, card-context seeding, live attribution signals, and focused web validation cadence, see <a href="/docs/analyst.html">Analyst Operator Guide</a>.</p><h2 id="unauthorized-api-or-websocket-access" tabindex="-1">Unauthorized API or WebSocket access <a class="header-anchor" href="#unauthorized-api-or-websocket-access" aria-label="Permalink to &quot;Unauthorized API or WebSocket access&quot;">​</a></h2><h3 id="symptoms" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h3><ul><li><code>401 Unauthorized</code> from <code>/api/*</code></li><li>UI shows unauthorized or no-token state</li><li>WebSocket does not connect</li><li>card detail shows <code>Unauthorized</code></li></ul><h3 id="what-to-check" tabindex="-1">What to check <a class="header-anchor" href="#what-to-check" aria-label="Permalink to &quot;What to check&quot;">​</a></h3><ol><li>Confirm the server token is configured.</li><li>Confirm the client is sending either: <ul><li><code>Authorization: Bearer &lt;token&gt;</code></li><li><code>?token=&lt;token&gt;</code></li></ul></li><li>Confirm <code>/health</code> works without auth.</li><li>Confirm <code>/docs/</code> is still reachable publicly.</li></ol><h2 id="preview-only-or-denied-control-action" tabindex="-1">Preview-only or denied control action <a class="header-anchor" href="#preview-only-or-denied-control-action" aria-label="Permalink to &quot;Preview-only or denied control action&quot;">​</a></h2><h3 id="symptoms-1" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms-1" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h3><ul><li>chat or REST mutation returns a preview instead of applying</li><li>response says confirmation or <code>preview_hash</code> is required</li><li>response says the action is denied by authorization policy</li><li><code>PendingConfirmationsPanel</code> shows a rejected preview-only action</li></ul><h3 id="meaning" tabindex="-1">Meaning <a class="header-anchor" href="#meaning" aria-label="Permalink to &quot;Meaning&quot;">​</a></h3><p>The static authz table classified the action as either:</p><ul><li><code>preview_only</code> — safe to preview, not safe to commit without a matching confirmation hash</li><li><code>deny</code> — not allowed for the current actor/surface/safety-class combination</li></ul><p>For <code>run_shell_command</code>, destructive analyst web-chat requests use the preview-only path rather than immediate execution, while Telegram does not expose the tool at all.</p><h3 id="what-to-do" tabindex="-1">What to do <a class="header-anchor" href="#what-to-do" aria-label="Permalink to &quot;What to do&quot;">​</a></h3><ol><li>Confirm the action is being attempted from the intended surface (<code>web-chat</code>, <code>web-ui</code>, <code>rest</code>, <code>cli</code>, or <code>telegram</code>).</li><li>Re-submit with <code>confirmed: true</code> and the matching preview hash if the action is preview-only.</li><li>If the action should be allowed by policy, inspect the authz table customization in <code>src/agents/authz.ts</code> rather than adding a one-off bypass.</li><li>Check <code>.saivage/runtime/control-actions.jsonl</code> or <code>/api/control-actions</code> to confirm whether the request was rejected or denied.</li></ol><h2 id="card-detail-says-card-not-found" tabindex="-1">Card detail says card not found <a class="header-anchor" href="#card-detail-says-card-not-found" aria-label="Permalink to &quot;Card detail says card not found&quot;">​</a></h2><h3 id="symptoms-2" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms-2" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h3><ul><li>card detail shows <code>Card not found</code></li><li><code>GET /api/cards/:id</code> returns <code>404</code></li></ul><h3 id="meaning-1" tabindex="-1">Meaning <a class="header-anchor" href="#meaning-1" aria-label="Permalink to &quot;Meaning&quot;">​</a></h3><p>The card ID is wrong, the card was deleted, or the browser route is stale.</p><h3 id="what-to-do-1" tabindex="-1">What to do <a class="header-anchor" href="#what-to-do-1" aria-label="Permalink to &quot;What to do&quot;">​</a></h3><ol><li>Return to the Cards list and confirm the card still exists.</li><li>Refresh the Cards route.</li><li>If the card should exist, inspect recent delete/update activity in Debug.</li></ol><h2 id="card-detail-says-stale" tabindex="-1">Card detail says stale <a class="header-anchor" href="#card-detail-says-stale" aria-label="Permalink to &quot;Card detail says stale&quot;">​</a></h2><h3 id="symptoms-3" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms-3" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h3><ul><li>card detail banner says <code>This card detail may be stale</code></li><li>active card view shows a stale warning ribbon</li><li>analyst-triggered card updates or note changes appear after the current card view loaded</li></ul><h3 id="meaning-2" tabindex="-1">Meaning <a class="header-anchor" href="#meaning-2" aria-label="Permalink to &quot;Meaning&quot;">​</a></h3><p>A relevant WebSocket event or operator notification arrived after the last successful detail fetch or acknowledgement.</p><p>Common causes:</p><ul><li>tracked card edit created a <code>card_changed</code> notification</li><li>directive or escalation note was added</li><li>runtime pause/freeze/process changes affected the viewed work</li><li>a live analyst mutation arrived with attribution or an analyst-action toaster</li></ul><h3 id="what-to-do-2" tabindex="-1">What to do <a class="header-anchor" href="#what-to-do-2" aria-label="Permalink to &quot;What to do&quot;">​</a></h3><ol><li>Use <strong>Refresh card</strong>.</li><li>Re-check evidence, review, dispatch summaries, and card history before treating the card as complete.</li><li>Review notifications to see whether a blocking change is still pending.</li><li>If the change came from an analyst chat turn, inspect the current transcript chips and card history attribution for confirmation.</li></ol><h2 id="running-agent-ignored-a-change-or-cannot-finish" tabindex="-1">Running agent ignored a change or cannot finish <a class="header-anchor" href="#running-agent-ignored-a-change-or-cannot-finish" aria-label="Permalink to &quot;Running agent ignored a change or cannot finish&quot;">​</a></h2><h3 id="symptoms-4" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms-4" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h3><ul><li>operator changed a card or added a directive/escalation note</li><li>agent later appears stale or continues old work</li><li>executor/reviewer cannot finalize and dispatch is held</li><li>logs mention blocking notifications or acknowledgement requirements</li></ul><h3 id="meaning-3" tabindex="-1">Meaning <a class="header-anchor" href="#meaning-3" aria-label="Permalink to &quot;Meaning&quot;">​</a></h3><p>The runtime delivers operator changes at the next safe point through session notifications. <code>block</code> severity changes must be acknowledged before executor/reviewer terminal results are accepted.</p><p>Typical blocking triggers:</p><ul><li>card <code>acceptance</code>, <code>description</code>, <code>instructions_file</code>, or <code>depends_on</code> edits</li><li>escalation notes</li><li>runtime pause/freeze</li></ul><h3 id="what-to-do-3" tabindex="-1">What to do <a class="header-anchor" href="#what-to-do-3" aria-label="Permalink to &quot;What to do&quot;">​</a></h3><ol><li>Inspect card history or notes to confirm the exact change.</li><li>Inspect the session conversation for the synthetic operator-update message.</li><li>Ensure the agent used <code>diff_card</code>, <code>get_card_history_entry</code>, <code>get_note</code>, or similar read tools as needed.</li><li>Ensure the session acknowledged the blocking notification.</li><li>If the dispatch is still held after reinvocation, treat it as an agent/tooling issue rather than forcing completion.</li></ol><h2 id="resume-failed-from-frozen-or-error-state" tabindex="-1">Resume failed from frozen or error state <a class="header-anchor" href="#resume-failed-from-frozen-or-error-state" aria-label="Permalink to &quot;Resume failed from frozen or error state&quot;">​</a></h2><h3 id="symptoms-5" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms-5" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h3><ul><li><code>/api/runtime/resume</code> returns an actionable error</li><li>analyst/CLI resume says to use <code>resume-from-freeze</code></li><li>runtime stays frozen</li></ul><h3 id="meaning-4" tabindex="-1">Meaning <a class="header-anchor" href="#meaning-4" aria-label="Permalink to &quot;Meaning&quot;">​</a></h3><p>Generic resume is intentionally rejected for <code>frozen</code> and <code>error</code> states. This is a safety rule, not a drift bug.</p><h3 id="what-to-do-4" tabindex="-1">What to do <a class="header-anchor" href="#what-to-do-4" aria-label="Permalink to &quot;What to do&quot;">​</a></h3><ol><li>If the runtime is <code>frozen</code>, use <code>POST /api/runtime/resume-from-freeze</code>.</li><li>If the runtime is <code>error</code>, fix the underlying failure and follow the freeze/recovery path rather than forcing generic resume.</li><li>Confirm the freeze manifest exists when using resume-from-freeze.</li></ol><h2 id="generated-file-preview-is-blocked-or-redacted" tabindex="-1">Generated file preview is blocked or redacted <a class="header-anchor" href="#generated-file-preview-is-blocked-or-redacted" aria-label="Permalink to &quot;Generated file preview is blocked or redacted&quot;">​</a></h2><h3 id="symptoms-6" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms-6" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h3><ul><li>card detail says preview blocked</li><li>card detail shows a blocked reason</li><li>Files view returns <code>403</code></li><li>preview shows <code>[REDACTED]</code></li></ul><h3 id="expected-causes" tabindex="-1">Expected causes <a class="header-anchor" href="#expected-causes" aria-label="Permalink to &quot;Expected causes&quot;">​</a></h3><ul><li>blocked sensitive file such as <code>.saivage/auth-profiles.json</code></li><li>redacted-only file such as <code>.saivage/saivage.json</code></li><li>containment violation</li><li>oversized file</li><li>binary file</li><li>symlink that resolves outside the project root</li></ul><h3 id="what-to-do-5" tabindex="-1">What to do <a class="header-anchor" href="#what-to-do-5" aria-label="Permalink to &quot;What to do&quot;">​</a></h3><ul><li>treat blocked/redacted states as expected safety behavior first;</li><li>use the blocked reason shown in card detail to distinguish containment vs sensitivity problems;</li><li>avoid bypassing the API unless you are in a controlled maintenance or forensic workflow.</li><li>if the question is specifically about analyst inspection boundaries, confirm the request against the <a href="/docs/analyst.html">Analyst Operator Guide</a>.</li></ul><h2 id="focused-analyst-web-validation-command-confusion" tabindex="-1">Focused analyst web validation command confusion <a class="header-anchor" href="#focused-analyst-web-validation-command-confusion" aria-label="Permalink to &quot;Focused analyst web validation command confusion&quot;">​</a></h2><h3 id="symptoms-7" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms-7" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h3><ul><li>an operator tries to validate analyst web UI regressions with root <code>npm test</code></li><li>Jest reports no matching suites for Vue analyst files under <code>web/src/__tests__</code></li><li>validation evidence does not clearly show whether analyst chat/card live-update suites actually ran</li></ul><h3 id="meaning-5" tabindex="-1">Meaning <a class="header-anchor" href="#meaning-5" aria-label="Permalink to &quot;Meaning&quot;">​</a></h3><p>Root <code>npm test</code> is a Jest runner scoped to the backend <code>tests/</code> tree. The shipped analyst web UI suites run under <strong>Vitest from <code>/work/saivage-v3/web</code></strong>.</p><h3 id="what-to-do-6" tabindex="-1">What to do <a class="header-anchor" href="#what-to-do-6" aria-label="Permalink to &quot;What to do&quot;">​</a></h3><ol><li>Run the focused analyst web suites from <code>/work/saivage-v3/web</code>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/analyst-chat-panel.test.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/analyst-chat-store.test.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/app-shell-analyst-drawer.test.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/analyst-toaster.test.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/card-detail-view.test.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/card-history-panel-analyst-filter.test.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/__tests__/ws-store.test.ts</span></span></code></pre></div><ol start="2"><li>Or use the root delegating wrapper:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web:test:analyst-ui</span></span></code></pre></div><ol start="3"><li>If validation notes mention root Jest for these suites, correct the record and rerun with Vitest before accepting the result.</li></ol><h2 id="card-detail-shows-missing-or-incomplete-evidence" tabindex="-1">Card detail shows missing or incomplete evidence <a class="header-anchor" href="#card-detail-shows-missing-or-incomplete-evidence" aria-label="Permalink to &quot;Card detail shows missing or incomplete evidence&quot;">​</a></h2><h3 id="symptoms-8" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms-8" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h3><ul><li><code>No operator-facing evidence is recorded yet</code></li><li><code>This terminal or blocked card has no operator-facing evidence recorded</code></li><li><code>recorded evidence file is missing from the workspace</code></li></ul><h3 id="meaning-6" tabindex="-1">Meaning <a class="header-anchor" href="#meaning-6" aria-label="Permalink to &quot;Meaning&quot;">​</a></h3><p>These states are different:</p><ul><li><code>none recorded yet</code> — active/running work has not produced operator-facing evidence yet</li><li><code>incomplete</code> — a blocked/done/failed card lacks usable operator-facing evidence</li><li><code>missing files</code> — evidence references were recorded, but the file is gone now</li></ul><h3 id="what-to-do-7" tabindex="-1">What to do <a class="header-anchor" href="#what-to-do-7" aria-label="Permalink to &quot;What to do&quot;">​</a></h3><ol><li>Check verification commands, review result, and dispatch summary on the same card.</li><li>Inspect child/evidence-card links from the detail view.</li><li>Inspect card history to see whether the acceptance criteria changed after the evidence was produced.</li><li>Do not accept completion based on status alone when evidence is incomplete.</li></ol><h2 id="review-result-shows-failed-or-not-reviewed" tabindex="-1">Review result shows failed or not reviewed <a class="header-anchor" href="#review-result-shows-failed-or-not-reviewed" aria-label="Permalink to &quot;Review result shows failed or not reviewed&quot;">​</a></h2><h3 id="symptoms-9" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms-9" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h3><ul><li>card detail shows <code>Review failed</code></li><li>card detail shows <code>Not reviewed</code></li></ul><h3 id="meaning-7" tabindex="-1">Meaning <a class="header-anchor" href="#meaning-7" aria-label="Permalink to &quot;Meaning&quot;">​</a></h3><p>A card marked <code>done</code> is not automatically operator-accepted. Use review status plus evidence/dispatch state.</p><h3 id="what-to-do-8" tabindex="-1">What to do <a class="header-anchor" href="#what-to-do-8" aria-label="Permalink to &quot;What to do&quot;">​</a></h3><ul><li>review <code>achieved</code>, <code>missing</code>, and <code>evidence cards</code> in the detail view;</li><li>inspect cited evidence cards through the card-detail navigation links;</li><li>if review is missing for a done card, treat completion as unverified.</li></ul>',82)])])}const p=a(s,[["render",r]]);export{m as __pageData,p as default};
